const E_SOURCES={"feb": {"name": "Febraban · Pesquisa de Tecnologia Bancária 2026", "date": "26 jun 2026 · transações: ano-base 2025; orçamento: projeção 2026", "url": "https://portal.febraban.org.br/noticia/4469/pt-br/"}, "fsb": {"name": "FSB · Práticas para adoção responsável de IA", "date": "15 out 2026 · relatório final", "url": "https://www.fsb.org/2026/10/fsb-finalises-sound-practices-for-the-responsible-adoption-of-artificial-intelligence-ai/"}, "boe": {"name": "Bank of England · IA e estabilidade financeira", "date": "9 abr 2025 · análise do sistema financeiro britânico", "url": "https://www.bankofengland.co.uk/financial-stability-in-focus/2025/april-2025"}, "legacy": {"name": "GOV.UK · Avaliação de risco de sistemas legados", "date": "Atualizado em 17 ago 2026 · referência do setor público britânico", "url": "https://www.gov.uk/government/publications/guidance-on-the-legacy-it-risk-assessment-framework/guidance-on-the-legacy-it-risk-assessment-framework"}, "bc": {"name": "Banco Central · Cinco anos de Open Finance", "date": "Ago 2025 · crédito acumulado de 2021 a 30 jun 2025", "url": "https://www.bcb.gov.br/detalhenoticia/20813/noticia"}, "consent": {"name": "Banco Central · Cancelamento de consentimento", "date": "FAQ consultada em 22 out 2026", "url": "https://bcb.gov.br/meubc/faqs/p/como-cancelar-uma-autorizacao-no-open-finance"}};
const E_ARTICLES=[{"slug": "construir-por-composicao", "topic": "modernizacao", "tag": "Modernização & eficiência", "title": "Modernizar sem recomeçar o banco.", "dek": "Como transformar uma demanda de produto em uma evolução delimitada — e evitar que a próxima entrega carregue mais uma cópia da mesma regra.", "short": "Evoluir uma jornada preservando o que funciona. Onde começar, o que compartilhar e como medir.", "art": "bridge", "signal": "R$ 50,4 bi", "signalLabel": "Orçamento tecnológico projetado para os bancos em 2026.", "source": "feb", "thesis": "O melhor ponto de partida é uma mudança que você consegue delimitar, medir e reverter.", "sections": [["O que o mercado está pedindo", "O orçamento projetado pela pesquisa Febraban 2026 mostra a dimensão do investimento em tecnologia. O dado não prova retorno, nem preferência por uma arquitetura específica. A pergunta editorial é outra: quanto desse esforço aumenta a capacidade de entregar o próximo produto?", "A pressão aparece quando uma mudança comercial exige alterações em vários canais, integrações e rotinas de operação. Um novo prazo de crédito ou uma nova condição de acesso deixa de ser uma decisão localizada e passa a disputar uma janela de entrega de toda a organização."], ["Escolha uma fronteira de negócio", "Um recorte útil pode ser a simulação de uma proposta, a verificação de identidade ou a formalização. Ele precisa ter entrada, saída, responsável e resultado observável. Escolher uma capacidade só porque é simples de extrair pode produzir uma API nova sem melhorar o trabalho de ninguém.", "Considere uma instituição que apresenta condições diferentes no app, no portal do parceiro e na mesa. Concentrar o cálculo em uma capacidade com contrato explícito cria um lugar para discutir a regra. Os canais continuam distintos, mas consomem a mesma responsabilidade."], ["A convivência é parte da solução", "A migração precisa definir onde está o dado oficial, quais operações podem ser repetidas e como comparar respostas. Durante a transição, executar cálculos em paralelo pode ajudar a encontrar diferenças antes de encaminhar tráfego real. Operações que movimentam dinheiro exigem outro cuidado: repetir uma chamada não pode repetir o efeito.", "Uma fronteira modular não elimina acoplamento por si só. Versões, tratamento de falhas e compatibilidade precisam ser combinados com os consumidores. Quando uma capacidade ganha muitos usuários, uma mudança mal governada pode ampliar o impacto em vez de reduzi-lo."], ["Quando compartilhar — e quando preservar a diferença", "Há reúso quando dois produtos precisam da mesma responsabilidade e aceitam um contrato comum. Há apenas semelhança superficial quando nomes iguais escondem regras, ciclos de vida ou exigências diferentes. Forçar ambos para uma única implementação tende a transformar parâmetros em exceções difíceis de entender.", "A proposta é compartilhar o fundamento e manter explícito o contexto. Banking, crédito e recebíveis podem reutilizar identidade e documentos sem compartilhar a mesma política de aprovação. A arquitetura precisa permitir essa diferença."]], "exampleTitle": "Uma simulação, três experiências", "example": "Exemplo de desenho: app do cliente, portal do parceiro e mesa consomem cálculo e precificação. Cada canal organiza sua interface; política, parâmetros e versão permanecem identificáveis na base. A migração começa por uma modalidade, com comparação de resultados e plano de retorno.", "metrics": [["Prazo de mudança", "Tempo entre a regra aprovada e sua chegada aos canais."], ["Duplicação", "Quantas implementações da mesma regra ainda precisam mudar juntas."], ["Qualidade operacional", "Divergências de resultado, falhas e esforço de reconciliação."]], "questions": ["Qual regra hoje precisa ser alterada em mais de um lugar?", "Existe uma modalidade pequena o suficiente para validar a transição?", "Quem responde pelo contrato depois que o segundo produto passar a usá-lo?"], "connection": "Na Catalisa, portfólio, cálculo, precificação e decisão são responsabilidades que podem compor jornadas de crédito. A seleção depende do contrato e do estágio de cada capacidade; o catálogo não dispensa validação de integração.", "links": [["/arquitetura/", "Arquitetura"], ["/ecossistema/credit/", "Credit Platform"]], "sources": ["feb", "legacy"], "sourceNote": "O framework britânico usa probabilidade e impacto para priorizar risco de legado. Ele serve aqui como referência de análise, não como exigência para bancos brasileiros nem como recomendação de uma arquitetura específica."}, {"slug": "autonomia-responsabilidade", "topic": "ia", "tag": "IA aplicada & operação", "title": "A IA respondeu. A operação aconteceu?", "dek": "O salto entre uma conversa convincente e uma tarefa concluída exige ferramentas, estados e responsáveis. É aí que o agente encontra a arquitetura.", "short": "Do piloto ao processo: contexto, ferramentas e evidência de conclusão.", "art": "agency", "signal": "12 práticas", "signalLabel": "O FSB organiza governança e gestão do ciclo de vida da IA em seu relatório final de outubro de 2026.", "source": "fsb", "thesis": "Resposta gerada e ação concluída são estados diferentes do trabalho.", "sections": [["A demanda é concluir trabalho", "O relatório final do FSB trata de responsabilidades, dados, avaliação de desempenho, supervisão humana e dependências externas. A publicação oferece práticas adaptáveis ao contexto; não certifica ferramentas ou produtos.", "Nossa leitura é que a passagem do experimento para a operação depende de um objeto de trabalho claro. Em vez de medir apenas a qualidade da conversa, a equipe precisa definir qual tarefa pode ser concluída, por quem, com quais dados e sob quais limites."], ["Três responsabilidades em uma mesma jornada", "Interpretar uma solicitação é diferente de aplicar uma política e diferente de executar uma operação. A IA pode organizar linguagem e contexto; uma política pode determinar o encaminhamento; uma ferramenta autorizada realiza uma ação específica. Separar essas responsabilidades facilita testar o percurso.", "Em uma solicitação de renegociação, por exemplo, o assistente pode buscar o contrato permitido, resumir a demanda e solicitar uma simulação. Isso não concede autoridade automática para mudar condições, aceitar um acordo em nome do cliente ou executar uma transferência."], ["A ferramenta precisa devolver um estado verificável", "Uma ferramenta deve distinguir sucesso, recusa, pendência e falha. Se o sistema externo não confirmou o registro, a interface não deve comunicar que a operação terminou. Essa separação também ajuda a decidir se uma tentativa pode ser repetida ou deve seguir para análise.", "O contexto transmitido à equipe humana precisa incluir o que já foi consultado, o que foi proposto e o que ainda depende de ação. Encaminhar apenas a conversa inteira transfere ao operador o custo de reconstruir o caso. Um resumo verificável é mais útil que uma certeza aparente."], ["Comece pelo copiloto que reduz uma fila", "Um primeiro recorte pode preparar dossiês, localizar documentos ou organizar o atendimento para quem decide. O ganho aparece quando diminui o tempo de busca e preparação sem ocultar lacunas ou criar novos erros de execução.", "Depois, ações reversíveis e bem delimitadas podem ser adicionadas conforme a validação. A expansão deve acompanhar evidência de desempenho em situações reais, incluindo dados incompletos, ferramentas indisponíveis e solicitações fora do escopo. Uma demonstração feliz não cobre essas condições."]], "exampleTitle": "Copiloto para uma mesa de crédito", "example": "Cenário ilustrativo: a IA prepara um resumo do dossiê com referências aos documentos; a política identifica pendências; o analista revisa o material. A formalização só avança no estado autorizado. A IA apoia a leitura, enquanto a responsabilidade da decisão permanece definida.", "metrics": [["Trabalho concluído", "Casos encerrados corretamente, com confirmação no sistema de origem."], ["Retrabalho", "Correções humanas, reaberturas e ações duplicadas."], ["Tempo útil", "Tempo total de resolução, incluindo revisão e encaminhamento."]], "questions": ["O que conta como conclusão, além de uma resposta no chat?", "Qual ferramenta comprova que a ação aconteceu?", "Que informação acompanha o caso quando uma pessoa precisa assumir?"], "connection": "Agentes, workflows, dados e canais podem participar da mesma composição na Catalisa. A autoridade continua no desenho da jornada: ferramentas permitidas, regras, estados e pontos de revisão precisam ser definidos por operação.", "links": [["/agentes/", "Agentes IA"], ["/workflows/", "Workflows"]], "sources": ["fsb", "boe"], "sourceNote": "As práticas internacionais contextualizam a pauta. O exemplo da mesa é uma proposta editorial de desenho, não um caso de cliente nem uma declaração de conformidade."}, {"slug": "regra-legivel", "topic": "credito", "tag": "Crédito & decisão", "title": "Decidir rápido. Conseguir explicar depois.", "dek": "Uma esteira eficiente precisa distinguir dado, regra e execução. Velocidade só se torna sustentável quando a operação consegue reconstruir o percurso.", "short": "Política versionada, dados rastreáveis e exceções que chegam à pessoa certa.", "art": "decision", "signal": "Dado ≠ regra", "signalLabel": "Uma separação de responsabilidades para analisar, testar e revisar decisões.", "source": "boe", "thesis": "A resposta importa. O caminho que a produziu também é parte do produto.", "sections": [["Mais informação aumenta a responsabilidade", "O Bank of England aponta oportunidades da IA em decisões financeiras, acompanhadas de riscos relacionados a modelos e dados. Esse é um debate internacional, não uma medição do desempenho de motores brasileiros.", "Na prática de produto, uma pergunta permanece mesmo quando não há IA: se a política mudou, como descobrir quais operações usaram a versão anterior? A falta dessa ligação dificulta investigar divergências e explicar por que dois casos seguiram caminhos diferentes."], ["Buscar dados não é avaliar a política", "A esteira organiza fontes, disponibilidade e prazos. O motor avalia a regra publicada com as entradas recebidas. Um campo ausente, uma consulta que falhou e um valor válido igual a zero são situações diferentes; transformar todas em um mesmo número destrói informação relevante.", "O contrato de entrada deve preservar qualidade e origem suficientes para a política decidir como agir. Dependendo do desenho, o caso pode aguardar uma fonte, seguir por um percurso alternativo ou exigir revisão. Essa escolha precisa ser explícita, e não um efeito acidental do código."], ["Uma alteração de política pede comparação", "Antes de publicar uma regra nova, a equipe pode compará-la com a versão anterior usando uma amostra apropriada de casos. O objetivo é localizar mudanças de comportamento, avaliar exceções e investigar resultados inesperados. Isso não substitui validação de risco e de negócio.", "Registrar a versão executada ajuda a ligar a política ao resultado. Quando há modelo estatístico ou IA, registrar só a tabela não basta: as versões dos modelos e as transformações relevantes também fazem parte da explicação. Determinismo de uma regra e validade da política são propriedades diferentes."], ["A revisão humana precisa ter conteúdo", "Uma fila de exceções útil explica o motivo do encaminhamento, os dados faltantes, a política considerada e as ações permitidas. Enviar todos os casos incompletos para a mesa sem priorização pode preservar controle e, ao mesmo tempo, destruir eficiência.", "Por isso, o desenho deve discutir capacidade da fila e tempo de espera. Uma política que automatiza mais decisões, mas multiplica pendências difíceis, pode apenas mover o custo. A avaliação combina resultado, qualidade e esforço operacional."]], "exampleTitle": "Mesma entrada, versões diferentes", "example": "Laboratório conceitual: compare uma política que encaminha documentação incompleta para revisão com outra que solicita complementação primeiro. O objetivo não é sugerir critérios de concessão; é tornar visível como uma mudança de regra altera o trabalho da operação.", "metrics": [["Tempo por etapa", "Separar espera por fonte, execução de regra e análise humana."], ["Reconstituição", "Percentual de casos com entrada, origem, versão e resultado localizáveis."], ["Exceções", "Volume, motivo, idade da fila e taxa de retrabalho."]], "questions": ["Uma falha de fonte aparece como falha ou como reprovação?", "Você consegue localizar a política usada por uma operação específica?", "A mesa recebe uma pendência explicada ou apenas uma proposta sem resposta?"], "connection": "Decision Platform e Decision Engine têm papéis distintos na Catalisa: reunir fontes e avaliar políticas. A composição com cálculo, precificação e formalização deve preservar esses contratos e o estágio de cada componente.", "links": [["/ecossistema/decision/", "Decision"], ["/capacidades/decision-engine/", "Decision Engine"]], "sources": ["boe", "fsb"], "sourceNote": "As propostas de testes, filas e versionamento são análise editorial. Não constituem recomendação de política de crédito, promessa de aprovação ou resultado de cliente."}, {"slug": "open-finance-da-conexao-ao-produto", "topic": "credito", "tag": "Open Finance & produto", "title": "Conectar dados é só o começo.", "dek": "O diferencial aparece quando o dado compartilhado participa de uma jornada útil: com qualidade, política, oferta e acompanhamento.", "short": "O caminho entre consentimento, informação e uma experiência de crédito que faz sentido.", "art": "data", "signal": "R$ 31 bi", "signalLabel": "Crédito originado com análise de dados compartilhados, de 2021 a junho de 2025, segundo o Banco Central. Valor acumulado; não é projeção.", "source": "bc", "thesis": "Uma conexão só produz valor quando encontra uma decisão de produto.", "sections": [["O sinal de mercado tem um período", "O volume divulgado pelo Banco Central mostra uso de dados compartilhados em operações de crédito. Não mede retorno de uma plataforma específica, nem permite atribuir toda a concessão exclusivamente ao Open Finance.", "Para quem constrói produto, o desafio é transformar acesso autorizado em uma experiência compreensível. Pedir compartilhamento sem explicar que trabalho ele ajuda a resolver acrescenta uma etapa à jornada sem tornar evidente seu benefício."], ["Comece pela decisão que precisa de contexto", "Uma jornada possível é a revisão de uma proposta de capital de giro. A instituição define quais informações são relevantes, como avaliar sua qualidade e como tratar períodos incompletos. O cliente entende a finalidade do compartilhamento e acompanha o estado da solicitação.", "Conectar todos os dados disponíveis antes de escolher a pergunta tende a aumentar complexidade. O recorte deve partir da decisão de negócio: o que a informação adicional pode esclarecer e qual ação é possível depois da análise. Disponibilidade técnica não equivale a pertinência."], ["Consentimento é estado da jornada", "O Banco Central informa que o cliente pode cancelar a autorização de compartilhamento a qualquer momento. O produto precisa lidar com essa mudança e com falhas de consulta sem fingir que o fluxo continua nas mesmas condições.", "O desenho operacional também precisa distinguir o que aconteceu antes da revogação e quais novos acessos deixam de ser possíveis. Tratamento e retenção de dados já recebidos exigem avaliação específica. A interface deve oferecer encaminhamento claro, como continuar com informações permitidas ou solicitar outra ação ao cliente."], ["A oferta exige mais do que um conector", "Entre consulta e contratação existem normalização de dados, política, cálculo, precificação, formalização e acompanhamento. Uma composição útil torna essas etapas observáveis e permite evoluir uma delas sem esconder seus efeitos nas demais.", "O resultado deve ser medido por uma jornada completa: quantas solicitações chegam ao resultado esperado, onde os clientes abandonam e quais dados geram pendências. Aprovação, preço e risco continuam sob responsabilidade da instituição; mais dados não garantem melhores condições em todo caso."]], "exampleTitle": "Capital de giro com contexto compartilhado", "example": "Composição proposta: uma empresa autoriza o compartilhamento; a jornada verifica suficiência dos dados; a política orienta análise e pendências; o cálculo prepara condições; o cliente recebe uma oferta ou um próximo passo compreensível. Participação no ecossistema e integrações precisam ser validadas.", "metrics": [["Conversão da jornada", "Da autorização ao resultado, com perdas separadas por etapa."], ["Qualidade de dados", "Cobertura, atualidade e divergências relevantes para a política."], ["Esforço do cliente", "Complementações solicitadas e tempo até um próximo passo claro."]], "questions": ["Qual benefício concreto justifica pedir o compartilhamento?", "O que acontece se uma fonte falhar ou a autorização mudar?", "A equipe mede conexões feitas ou jornadas que chegaram a um resultado?"], "connection": "A leitura composable conecta dados, decisão, cálculo e documentos. O potencial está no desenho ponta a ponta; acesso a APIs, participação, contratos e disponibilidade das integrações precisam ser confirmados para cada projeto.", "links": [["/ecossistema/credit/", "Credit Platform"], ["/arquitetura/", "Arquitetura"]], "sources": ["bc", "consent"], "sourceNote": "Cenário de produto proposto pela Catalisa. O dado histórico do BC não representa tração, volume ou resultado da Catalisa."}, {"slug": "resiliencia-e-liberdade-de-evoluir", "topic": "operacao", "tag": "Resiliência & integrações", "title": "E se uma peça ficar indisponível?", "dek": "Uma arquitetura conectada também precisa mostrar suas dependências. Continuidade começa por saber o que pode esperar e o que não pode ser repetido.", "short": "Falhas, dependências e alternativas: a operação também faz parte da arquitetura.", "art": "resilience", "signal": "Dependência visível", "signalLabel": "Uma condição para discutir continuidade, alternativas e concentração de fornecedores.", "source": "boe", "thesis": "Modularidade cria uma fronteira. A continuidade precisa ser construída dentro dela.", "sections": [["A concentração muda o desenho do risco", "O Bank of England destaca que a dependência de poucos provedores de IA pode afetar serviços financeiros quando eles falham, especialmente se a migração para alternativas for difícil. A análise trata do sistema financeiro; não demonstra que toda dependência compartilhada produzirá uma falha sistêmica.", "Para a equipe de produto, a pergunta pode ser bem concreta: quais jornadas dependem desta consulta, deste provedor ou deste modelo? Um inventário de fornecedores é insuficiente se não revela os serviços que deixam de funcionar quando uma peça para."], ["Uma falha não tem sempre a mesma consequência", "Uma busca de informação pode ser adiada. Uma operação de pagamento pode estar pendente de confirmação e não deve ser repetida sem verificar seu estado. Uma falha na assinatura pode impedir a conclusão da formalização, embora outras partes do dossiê continuem disponíveis.", "Essas situações pedem respostas diferentes. O contrato precisa tornar visível se houve recusa, indisponibilidade, expiração ou resultado desconhecido. A interface acompanha essa distinção para que o usuário não seja orientado a repetir uma ação que pode já ter ocorrido."], ["Alternativa não é sinônimo de equivalência", "Um adaptador pode concentrar particularidades de um provedor, mas não garante troca imediata. Uma alternativa precisa entregar os campos necessários, preservar significado e atender requisitos operacionais. Autenticação, limites, prazos e efeitos também podem mudar.", "Testar uma alternativa significa verificar a jornada completa. Uma resposta tecnicamente válida pode ter semântica diferente. A escolha de fornecedor precisa considerar esse custo de mudança e as condições reais para ativar uma rota secundária."], ["Meça a recuperação como trabalho de produto", "Um exercício útil escolhe uma dependência e observa como a jornada se comporta sem ela. Quem é avisado? O caso pode esperar? Qual ação é bloqueada? Como o trabalho volta ao fluxo depois que o serviço se recupera?", "Essa conversa aproxima arquitetura, operação e atendimento. O objetivo não é prometer ausência de falhas, mas evitar estados ambíguos e recuperação improvisada. A continuidade precisa ter responsáveis e critérios de retorno, assim como uma funcionalidade tem critérios de aceite."]], "exampleTitle": "Consulta indisponível durante uma proposta", "example": "Exemplo ilustrativo: uma fonte não responde dentro do prazo. A jornada preserva o pedido e o motivo da pendência. Conforme a política, aguarda, encaminha para revisão ou usa uma alternativa previamente validada. Nenhuma dessas saídas é tratada automaticamente como reprovação do cliente.", "metrics": [["Impacto por dependência", "Jornadas afetadas e tempo de indisponibilidade percebido."], ["Estados ambíguos", "Casos sem confirmação de sucesso ou falha que exigem reconciliação."], ["Recuperação", "Tempo e intervenção necessários para retomar casos pendentes."]], "questions": ["Você sabe quais produtos param quando um fornecedor falha?", "Que operações podem ser repetidas com segurança?", "A alternativa já foi validada ou existe apenas no desenho?"], "connection": "Fronteiras de capacidade e adaptadores ajudam a localizar dependências na Catalisa. Observabilidade, tratamento de falhas e alternativas precisam ser configurados e testados na implantação; modularidade não equivale a continuidade automática.", "links": [["/governanca/", "Governança"], ["/desenvolvedores/", "Desenvolvedores"]], "sources": ["boe", "legacy"], "sourceNote": "Recomendações de desenho editorial. Não representam SLA, certificação, garantia de portabilidade ou disponibilidade de um provedor alternativo."}];
